const response = $input.first().json;
const offers = response.data || [];

const allowedDistricts = ['wola', 'srodmiescie', 'mokotow', 'zoliborz', 'bialoleka', 'bemowo', 'ursynow', 'ursus', 'praga', 'wlochy', 'ochota', 'bielany', 'targowek', 'wilanow'];
const results = [];

for (const offer of offers) {
  try {
    const offerUrl = (offer.url || '').toLowerCase();
    if (offerUrl.includes('otodom')) continue;
    if (offer.partner && offer.partner.code) continue;
    if (offer.external_url) continue;

    const isBusinessUser = offer.user && (offer.user.business || offer.user.is_business || offer.user.company_name);
    if (isBusinessUser) continue;

    let hasOtodomPhotos = false;
    if (offer.photos && Array.isArray(offer.photos)) {
      for (const p of offer.photos) {
        const photoUrl = (p.link || '').toLowerCase();
        if (photoUrl.includes('otodom') || photoUrl.includes('uicdn') || photoUrl.includes('rfrcdn')) {
          hasOtodomPhotos = true;
          break;
        }
      }
    }
    if (hasOtodomPhotos) continue;

    const params = offer.params || [];
    let rooms = '', is2Rooms = false, area = '', floor = '', rent = '', deposit = '';
    let price = 0, priceStr = '', currency = 'PLN';
    let isAgencyParam = false;

    for (const p of params) {
      const key = p.key || '';
      const val = p.value || {};

      if (key === 'private_business' && (val.key === 'business' || String(val.label).includes('Firm') || String(val.label).includes('Biuro'))) {
        isAgencyParam = true;
      }

      if (key === 'm') area = val.label || '';
      if (key === 'rooms') {
        rooms = val.label || '';
        const roomKey = String(val.key || '');
        const roomLabel = (val.label || '').toLowerCase();
        if (roomKey === '2' || roomLabel.includes('2') || roomLabel.includes('dwa')) {
          is2Rooms = true;
        }
      }
      if (key === 'floor_select') floor = val.label || '';
      if (key === 'rent') rent = val.label || '';
      if (key === 'deposit') deposit = val.label || '';
      if (key === 'price') {
        price = parseInt(val.value) || 0;
        priceStr = val.value || val.label || '';
        currency = val.currency || 'PLN';
      }
    }

    if (isAgencyParam) continue;
    if (!is2Rooms) continue;
    if (price < 4000) continue;

    const cityName = (offer.location?.city?.name || '').toLowerCase();
    const districtName = offer.location?.district?.name || '';

    if (cityName !== 'warszawa') continue;

    const districtLower = districtName.toLowerCase().replace(/ó/g, 'o').replace(/ś/g, 's').replace(/ł/g, 'l').replace(/ż/g, 'z').replace(/ź/g, 'z').replace(/ć/g, 'c').replace(/ń/g, 'n').replace(/ą/g, 'a').replace(/ę/g, 'e');
    let isAllowedDistrict = false;
    for (const d of allowedDistricts) {
      if (districtLower.includes(d)) {
        isAllowedDistrict = true;
        break;
      }
    }
    if (!isAllowedDistrict && districtName) continue;

    const photos = [];
    if (offer.photos && Array.isArray(offer.photos)) {
      for (const p of offer.photos) {
        if (p.link) photos.push(p.link.replace('{width}', '800').replace('{height}', '600'));
      }
    }

    const location = districtName ? ('Варшава, ' + districtName) : 'Варшава';
    const olxUrl = offer.url || '';

    let title = [rooms, area].filter(Boolean).join(', ') || offer.title || 'Квартира';

    let msg = '✨ ' + title + '\n';
    if (priceStr) msg += '💰 Орендна плата - ' + priceStr + ' ' + currency + '\n';
    msg += '\n📍 ' + location + '\n\n';
    if (floor) msg += '🏢 Поверх: ' + floor + '\n';
    if (deposit) msg += '💰 Кауція: ' + deposit + '\n';
    if (rent) msg += '📋 Чинш: ' + rent + '\n';
    msg += '\n📱 Перегляд можливий також онлайн.\nДля огляду пишіть: @stayX_pl';
    msg += '\n\n— — — — — — —\n🤖 Не підходить цей район чи ціна? Налаштуйте персональний пошук у нашому боті: @stayx_apartments_bot';

    results.push({
      json: {
        id: String(offer.id || ''),
        message: msg,
        messageWithUrl: msg + '\n\n🔗 ' + olxUrl,
        photos: JSON.stringify(photos),
        url: olxUrl,
        addedAt: $now.setZone('Europe/Warsaw').toFormat('yyyy-MM-dd HH:mm'),
        status: 'pending'
      }
    });
  } catch (err) {
    continue;
  }
}

console.log(`📊 Знайдено квартир: ${results.length}`);
return results.length > 0 ? results : [{ json: { skip: true } }];

const newItems = $('Parse & Filter').all();
const existingItems = $('Check Existing').all();

const existingIds = new Set();
for (const item of existingItems) {
  if (item.json.id) existingIds.add(String(item.json.id));
}

const toAdd = [];
for (const item of newItems) {
  if (item.json.id && !existingIds.has(String(item.json.id))) {
    toAdd.push(item);
  }
}

console.log(`📊 Існуючих в таблиці: ${existingIds.size}`);
console.log(`📥 Нових для додавання: ${toAdd.length}`);

return toAdd.length > 0 ? toAdd : [{ json: { skip: true } }];

const items = $input.all();
const allPending = items.filter(item => item.json.status === 'pending');

if (allPending.length === 0) {
  return [];
}

const results = allPending.map(item => {
  let photos = [];
  try {
    photos = JSON.parse(item.json.photos || '[]');
  } catch(e) {
    photos = [];
  }
  return {
    json: {
      ...item.json,
      photos: photos,
      rowNumber: item.json.row_number || item.json['row_number']
    }
  };
});

return results;

const item = $input.first().json;
const BOT_URL = 'https://api.telegram.org/bot8233865335:AAGcpS4RWAwOSglZ84KgbDi2uCS8Enkv8Dw';
const MAIN = '-1002046661958';
const ADMIN = '-1003864439857';

const photos = (item.photos || []).slice(0, 10);
const msg = item.message || '';
const msgUrl = item.messageWithUrl || '';

async function requestWithRetry(options) {
  let attempt = 0;
  while (attempt < 3) {
    try {
      return await this.helpers.httpRequest(options);
    } catch (e) {
      if (e.message && e.message.includes('429')) {
        attempt++;
        let waitTime = 10000;
        if (e.response && e.response.data && e.response.data.parameters && e.response.data.parameters.retry_after) {
          waitTime = e.response.data.parameters.retry_after * 1000;
        }
        await new Promise(r => setTimeout(r, waitTime));
      } else {
        throw e;
      }
    }
  }
}

try {
  if (photos.length > 1) {
    const media = photos.map((url, idx) => {
      const o = { type: 'photo', media: url };
      if (idx === 0 && msg) o.caption = msg.substring(0, 1024);
      return o;
    });
    const mediaUrl = photos.map((url, idx) => {
      const o = { type: 'photo', media: url };
      if (idx === 0 && msgUrl) o.caption = msgUrl.substring(0, 1024);
      return o;
    });

    await requestWithRetry.call(this, {
      method: 'POST',
      url: BOT_URL + '/sendMediaGroup',
      body: { chat_id: MAIN, media: media },
      json: true
    });

    await new Promise(r => setTimeout(r, 1000));

    await requestWithRetry.call(this, {
      method: 'POST',
      url: BOT_URL + '/sendMediaGroup',
      body: { chat_id: ADMIN, media: mediaUrl },
      json: true
    });
  } else if (photos.length === 1) {
    await requestWithRetry.call(this, {
      method: 'POST',
      url: BOT_URL + '/sendPhoto',
      body: { chat_id: MAIN, photo: photos[0], caption: msg.substring(0, 1024) },
      json: true
    });

    await new Promise(r => setTimeout(r, 1000));

    await requestWithRetry.call(this, {
      method: 'POST',
      url: BOT_URL + '/sendPhoto',
      body: { chat_id: ADMIN, photo: photos[0], caption: msgUrl.substring(0, 1024) },
      json: true
    });
  } else {
    await requestWithRetry.call(this, {
      method: 'POST',
      url: BOT_URL + '/sendMessage',
      body: { chat_id: MAIN, text: msg },
      json: true
    });

    await new Promise(r => setTimeout(r, 1000));

    await requestWithRetry.call(this, {
      method: 'POST',
      url: BOT_URL + '/sendMessage',
      body: { chat_id: ADMIN, text: msgUrl },
      json: true
    });
  }

  item.status = 'sent';
  return { json: item };
} catch (err) {
  item.status = 'error';
  item.error = err.message + ' - ' + JSON.stringify(err.response?.data || {});
  try {
    const errorMsg = '❌ Помилка квартири: ' + (item.url || item.id) + '\n\nПричина:\n' + String(item.error).substring(0, 1000);
    await this.helpers.httpRequest({ method: 'POST', url: BOT_URL + '/sendMessage', body: { chat_id: ADMIN, text: errorMsg }, json: true });
  } catch(e) {}
  return { json: item };
}
